import { spawnSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";

const args = process.argv.slice(2);
const runConfig = JSON.parse(
  readFileSync(resolve("config/run.config.json"), "utf8"),
);
const valueAfter = (name) => {
  const index = args.indexOf(name);
  if (index < 0) return undefined;
  const value = args[index + 1];
  if (!value || value.startsWith("--"))
    throw new Error(`${name} requires a value.`);
  return value;
};
const optionValueIndexes = new Set(
  args.flatMap((value, index) =>
    ["--env", "--profile", "--scenario"].includes(value) ? [index + 1] : [],
  ),
);
const positionalEnvironment = args.find(
  (value, index) =>
    !value.startsWith("--") &&
    !optionValueIndexes.has(index) &&
    existsSync(resolve("test-data", `${value}.json`)),
);
const environment =
  valueAfter("--env") ?? positionalEnvironment ?? runConfig.environment;
const profile = valueAfter("--profile") ?? runConfig.profile;
const grafana = args.includes("--grafana");
const scenario = valueAfter("--scenario");
const dataPath = resolve("test-data", `${environment}.json`);
if (!existsSync(dataPath))
  throw new Error(`Missing performance test data: ${dataPath}`);
const version = spawnSync("k6", ["version"], { stdio: "ignore" });
if (version.status !== 0)
  throw new Error(
    "k6 is not installed or not on PATH. Install it from https://grafana.com/docs/k6/latest/set-up/install-k6/",
  );
const k6Args = [
  "run",
  ...(grafana ? ["-o", "experimental-prometheus-rw"] : []),
  ...(scenario ? ["--scenario", scenario] : []),
  "-e",
  `K6_ENV=${environment}`,
  "-e",
  `K6_PROFILE=${profile}`,
  "{{K6_ENTRY}}",
];
const env = {
  ...process.env,
  ...(grafana
    ? {
        K6_PROMETHEUS_RW_SERVER_URL: "http://localhost:9090/api/v1/write",
        K6_PROMETHEUS_RW_TREND_STATS: "p(90),p(95),p(99),min,max",
      }
    : {}),
};
console.log(
  `[RUN] k6 {{FRAMEWORK}} | environment=${environment} | profile=${profile} | grafana=${grafana}`,
);
const result = spawnSync("k6", k6Args, { stdio: "inherit", env });
process.exit(result.status ?? 1);
